@extends('layouts.app')
@section('content')
<style>
html,body{margin:0;padding:0;background:#fff;font-family:Arial,Helvetica,sans-serif}
.map-wrapper{position:relative;width:100%;max-width:1529px;margin:0 auto;overflow:visible}
.map-wrapper>svg{display:block;width:100%;height:auto;overflow:visible}
.map-hotspot{fill:transparent !important;stroke:transparent !important;stroke-width:2;cursor:pointer;pointer-events:all;vector-effect:non-scaling-stroke;transition:fill .15s ease,stroke .15s ease,stroke-width .15s ease}
.map-hotspot:hover,.map-hotspot.is-hovered{fill:rgba(255,94,35,.30) !important;stroke:#ff5e23 !important;stroke-width:3 !important}
.dome-hotspot{rx:34px;ry:25px;}
.dome-hotspot:hover,.dome-hotspot.is-hovered{fill:rgba(255,94,35,.18)!important;stroke:#ff9a00!important;stroke-width:4!important;filter:drop-shadow(0 0 6px rgba(255,154,0,.45));}

.map-popup{position:absolute;left:0;top:0;width:min(330px,calc(100vw - 24px));background:#fff;border:0;border-radius:16px;box-shadow:0 16px 40px rgba(10,25,45,.24),0 3px 12px rgba(10,25,45,.10);padding:7px 7px 14px;z-index:99999;display:none;transform:translateZ(0);overflow:visible;box-sizing:border-box}
.map-popup.is-visible{display:block;animation:popupIn .18s ease-out}
@keyframes popupIn{from{opacity:0;transform:translateY(7px) scale(.985)}to{opacity:1;transform:translateY(0) scale(1)}}
.map-popup::after{content:"";position:absolute;left:50%;bottom:-11px;transform:translateX(-50%);width:0;height:0;border-left:12px solid transparent;border-right:12px solid transparent;border-top:12px solid #fff;filter:drop-shadow(0 5px 4px rgba(10,25,45,.08))}
.popup-media{position:relative;width:100%;height:150px;border-radius:11px;overflow:hidden;background:#e9eef2}
.popup-image{display:block;width:100%;height:100%;object-fit:cover;margin:0}
.popup-close{position:absolute;top:9px;right:9px;width:34px;height:34px;border:0;border-radius:50%;background:rgba(255,255,255,.96);box-shadow:0 5px 18px rgba(0,0,0,.15);font-size:22px;line-height:1;color:#172b40;cursor:pointer;padding:0;z-index:2;font-weight:300}
.popup-content{padding:11px 12px 0}
.popup-heading{display:flex;align-items:center;gap:8px;margin:0 0 6px;font-size:20px;line-height:1.15;font-weight:700;color:#172b40;letter-spacing:-.5px}
.popup-badge{width:30px;height:30px;border-radius:50%;background:#ef5b3f;color:#fff;display:inline-flex;align-items:center;justify-content:center;font-size:13px;flex:none;font-weight:700}
.popup-location{display:flex;align-items:center;gap:6px;color:#24394e;font-size:13px;line-height:1.35;margin:0 0 8px}
.popup-location-icon{width:17px;height:17px;display:inline-flex;align-items:center;justify-content:center;color:#159bb5;font-size:16px;flex:none}
.popup-divider{height:1px;background:#dfe4e8;margin:0 0 18px}
.popup-body{font-size:18px;line-height:1.65;color:#41566b;margin:0 0 18px}
.popup-stats{display:grid;grid-template-columns:repeat(3,1fr);border-top:1px solid #e1e5e8;padding-top:9px;margin-top:2px}
.popup-stat{display:flex;align-items:center;justify-content:center;gap:5px;padding:2px 4px;color:#20384e;font-size:11px;border-right:1px solid #dfe4e8}
.popup-stat:last-child{border-right:0}
.popup-stat-icon{font-size:16px;line-height:1}
.popup-action{display:inline-flex;align-items:center;gap:7px;margin-top:9px;color:#ef6a50;font-weight:700;font-size:13px;text-decoration:none;cursor:pointer}
.popup-action:hover{text-decoration:underline}
@media(max-width:600px){.map-popup{width:min(300px,calc(100vw - 20px));border-radius:14px;padding:6px 6px 12px}.popup-media{height:135px;border-radius:10px}.popup-content{padding:9px 10px 0}.popup-heading{font-size:18px}.popup-badge{width:28px;height:28px;font-size:12px}.popup-location{font-size:12px}.popup-body{font-size:12px}.popup-stat{font-size:10px;gap:4px;padding:2px 2px}.popup-stat-icon{font-size:14px}.popup-close{width:30px;height:30px;font-size:20px;top:7px;right:7px}.popup-action{font-size:12px;margin-top:8px}}
</style>


