  '24': { title:'STUDIO 05 - Lake Sumner', body:'This space is available.<br>10:00 &mdash; 21:00', image:'https://assets.guesty.com/image/upload/v1781384206/production/64b00434b78496e69c8f5da9/hvcnftkhbxyv7hwccu2n.jpg', url:'/properties/64c26ff8b4927c003ed485e4', location:'Available Space', guests:'3 People', beds:'1 Bedrooms', baths:'1 Baths' },
  '25': { title:'STUDIO 01 - Lake Sumner', body:'This space is available.<br>10:00 &mdash; 21:00', image:'https://assets.guesty.com/image/upload/v1780965778/production/64b00434b78496e69c8f5da9/li7uapfsxg6ivf7sexr0.jpg', url:'/properties/64c26ff7b4927c003ed483ff', location:'Available Space', guests:'3 People', beds:'1 Bedrooms', baths:'1 Baths' },
  '26': { title:'STUDIO 02 - Lake Sumner', body:'This space is available.<br>10:00 &mdash; 21:00', image:'https://assets.guesty.com/image/upload/v1780965939/production/64b00434b78496e69c8f5da9/zmzf9bm5a7z9hosjntx0.jpg', url:'/properties/64c26ff732ba750048b1d46e', location:'Available Space', guests:'3 People', beds:'1 Bedrooms', baths:'1 Baths' },
  '27': { title:'ROOM 04 - Lake Sumner', body:'This space is available.<br>10:00 &mdash; 21:00', image:'https://assets.guesty.com/image/upload/v1779987085/production/64b00434b78496e69c8f5da9/qkhjmksupjlkwbrtjlr1.jpg', url:'/properties/64c26ff6b4927c003ed48246', location:'Available Space', guests:'2 People', beds:'1 Bedrooms', baths:'1 Baths' },
  '28': { title:'ROOM 03 - Lake Sumner', body:'This space is available.<br>10:00 &mdash; 21:00', image:'https://assets.guesty.com/image/upload/v1782498622/production/64b00434b78496e69c8f5da9/mxh1s5zrqbaqk05twb6j.jpg', url:'/properties/64c26ff5b4927c003ed48093', location:'Available Space', guests:'2 People', beds:'1 Bedrooms', baths:'1 Baths' },
  '29': { title:'Mount Dora - Lake Jem', body:'This space is available.<br>10:00 &mdash; 21:00', image:'https://assets.guesty.com/image/upload/v1721426060/production/64b00434b78496e69c8f5da9/mlcrjuuacxgnspemz21z.jpg', url:'/properties/64c26ff4b4927c003ed47b53', location:'Available Space', guests:'6 People', beds:'3 Bedrooms', baths:'3 Baths' }
}

  // Dome popup data — same popup design as the numbered spaces.
  Object.assign(details, {
    'Dome 1': { title:'Summer Lake Tiny House', body:'This dome is available.<br>10:00 &mdash; 21:00', image:'https://assets.guesty.com/image/upload/v1721425959/production/64b00434b78496e69c8f5da9/amyiglch79r26emnhypt.jpg', url:'#', location:'Lake Summer', guests:'2-4 People', beds:'1&2 Bedrooms', baths:'1 Bath' },
    'Dome 2': { title:'Lake Summer Studio 1&2', body:'This dome is available.<br>10:00 &mdash; 21:00', image:'https://assets.guesty.com/image/upload/v1780965822/production/64b00434b78496e69c8f5da9/acwisnsre0lvjcvrsgj2.jpg', url:'#', location:'Lake Summer', guests:'3 People', beds:'1 Bedrooms', baths:'1 Bath' },
    'Dome 3': { title:'Summer Lake House', body:'This dome is available.<br>10:00 &mdash; 21:00', image:'https://assets.guesty.com/image/upload/v1721425970/production/64b00434b78496e69c8f5da9/ww4mhvz5gs3aujw4bc7t.jpg', url:'#', location:'Lake Summer', guests:'4-7 People', beds:'2&3 Bedrooms', baths:'3 Bath' },
    'Dome 4': { title:'Nest, Room 3&4, Studio 5', body:'This dome is available.<br>10:00 &mdash; 21:00', image:'https://assets.guesty.com/image/upload/v1784858224/production/64b00434b78496e69c8f5da9/opmntankfqztugflmwab.jpg', url:'#', location:'Lake Summer', guests:'2-3 People', beds:'0-1 Bedrooms', baths:'1 Bath' },
  });

  function getId(el){
    return (el.dataset.space || '').trim() || 'Space';
  }

  function getDetails(el){
    const id = getId(el);
    const key = id.replace(/^Space\s*/i, '');
    return details[key] || details[id] || {
      title: id.startsWith('Space ') ? id : 'Space ' + id,
      body: 'This space is available.<br>10:00 &mdash; 21:00',
      image: '',
      url: '#',
      location: 'Available Space',
      guests: '8 People',
      beds: '3 Bedrooms',
      baths: '3 Baths'
    };
  }

  function clearHover(){
    hotspots.forEach(h => h.classList.remove('is-hovered'));
  }

  function highlight(el){
    clearHover();
    el.classList.add('is-hovered');
  }

  function place(el){
    if(!el || !popup.classList.contains('is-visible')) return;

    const wr = wrapper.getBoundingClientRect();
    const r = el.getBoundingClientRect();
    const pw = popup.offsetWidth;
    const ph = popup.offsetHeight;
    const pad = 10;

    let left = r.left - wr.left + (r.width / 2) - (pw / 2);
    let top = r.top - wr.top - ph - 14;

    // Keep popup inside the map container horizontally.
    left = Math.max(pad, Math.min(left, wrapper.clientWidth - pw - pad));

    // If there isn't enough room above, place it below the lot.
    if(top < pad){
      top = r.bottom - wr.top + 14;
    }

    // Keep it inside vertically when possible.
    const maxTop = Math.max(pad, wrapper.clientHeight - ph - pad);
    top = Math.min(top, maxTop);

    popup.style.left = left + 'px';
    popup.style.top = top + 'px';
  }

  function show(el){
    clearTimeout(popupTimer);
    active = el;
    highlight(el);

    const id = getId(el);
    const d = getDetails(el);

    badge.textContent = id.replace(/^Space\s*/i, '').replace(/^Dome\s*/i, '');
    title.textContent = d.title;
    body.innerHTML = d.body;
    popupLocation.textContent = d.location || 'Available Space';

    const hasStats = d.guests || d.beds || d.baths;
    popupStats.style.display = hasStats ? 'grid' : 'none';
    popupGuests.textContent = d.guests || '8 People';
    popupBeds.textContent = d.beds || '3 Bedrooms';
    popupBaths.textContent = d.baths || '3 Baths';
    popupImage.src = d.image || 'data:image/jpeg;base64,';
    if (d.url) {
      popupAction.href = d.url;
      popupAction.style.display = 'inline-block';
    } else {
      popupAction.removeAttribute('href');
      popupAction.style.display = 'none';
    }
    popupImage.alt = d.title || (id.replace(/^Space\s*/i, '') || 'Space');

    popup.classList.add('is-visible');
    popup.setAttribute('aria-hidden','false');

    requestAnimationFrame(() => place(el));
  }

  function hide(){
    clearTimeout(popupTimer);
    popup.classList.remove('is-visible');
    popup.setAttribute('aria-hidden','true');
    clearHover();
    active = null;
  }

  function delayedHide(){
    clearTimeout(popupTimer);
    popupTimer = setTimeout(() => {
      if(!popup.matches(':hover') && !(active && active.matches(':hover'))){
        hide();
      }
    }, 120);
  }

  hotspots.forEach((el) => {
    // JS class highlighting is used in addition to :hover so the effect
    // remains reliable even when SVG/browser rendering is inconsistent.
    el.addEventListener('pointerenter', () => show(el));
    el.addEventListener('pointermove', () => {
      if(active !== el) show(el);
      else place(el);
    });
    el.addEventListener('pointerleave', delayedHide);

    // Keep click behavior working exactly as before.
    el.addEventListener('click', (event) => {
      event.stopPropagation();
      show(el);
    });
  });

  popup.addEventListener('pointerenter', () => clearTimeout(popupTimer));
  popup.addEventListener('pointerleave', delayedHide);
  close.addEventListener('click', (event) => {
    event.stopPropagation();
    hide();
  });

  // Clicking empty map space closes the popup.
  svg.addEventListener('click', (event) => {
    if(!event.target.closest('.map-hotspot')) hide();
  });

  window.addEventListener('resize', () => {
    if(active) place(active);
  });

  window.addEventListener('scroll', () => {
    if(active) place(active);
  }, {passive:true});
})();
</script>

@endsection